    CAST(RTRIM(d.[ItemCode]) AS nvarchar(200)) AS [itemCode],
    CAST(RTRIM(it.ItemName) AS nvarchar(200)) AS [itemName],
    CAST(NULL AS nvarchar(200)) AS [machine],
    CAST(d.[Qty] AS numeric(18,4)) AS [quantity],
    CAST(RTRIM(h.[comcode]) AS nvarchar(200)) AS [fromCompany],
    CAST(RTRIM(h.[SiteCode]) AS nvarchar(200)) AS [fromSite],
    CAST(RTRIM(h.[LocCode]) AS nvarchar(200)) AS [fromLocation],
    CAST(NULL AS nvarchar(200)) AS [fromBin],
    CAST(NULL AS nvarchar(200)) AS [toCompany],
    CAST(NULL AS nvarchar(200)) AS [toSite],
    CAST(NULL AS nvarchar(200)) AS [toLocation],
    CAST(NULL AS nvarchar(200)) AS [toBin],
    CAST(RTRIM(h.[CostCode]) AS nvarchar(200)) AS [costCentre]
  FROM dbo.[fAdjHed] h
  LEFT JOIN dbo.[fAdjDet] d ON d.[RefNo] = h.[RefNo]
  LEFT JOIN dbo.fItems it ON it.ItemCode = d.[ItemCode]
  LEFT JOIN txn m ON m.tbl = 'fAdjHed' AND m.code = RTRIM(h.[TxnType])

  UNION ALL

  SELECT
    CAST('FiRIssHed:' + RTRIM(h.[RefNo]) + ISNULL(':' + CAST(d.[RecordId] AS varchar(30)), '') AS nvarchar(200)) AS [lineId],
    CAST(N'Issue Note - Stock' AS nvarchar(200)) AS [type],
    CAST(RTRIM(h.[TxnType]) AS nvarchar(200)) AS [txnType],
    CAST('FiRIssHed' AS nvarchar(200)) AS [source],
    CAST(RTRIM(h.[RefNo]) AS nvarchar(200)) AS [reference],
    CAST(h.[TxnDate] AS date) AS [date],
    CAST(RTRIM(h.[ManuRef]) AS nvarchar(200)) AS [manualNo],
    CAST(RTRIM(d.[ItemCode]) AS nvarchar(200)) AS [itemCode],
    CAST(RTRIM(it.ItemName) AS nvarchar(200)) AS [itemName],
    CAST(NULL AS nvarchar(200)) AS [machine],
    CAST(d.[Qty] AS numeric(18,4)) AS [quantity],
    CAST(RTRIM(h.[ComCode]) AS nvarchar(200)) AS [fromCompany],
    CAST(COALESCE(NULLIF(RTRIM(h.[SiteCode]), ''), NULLIF(RTRIM(d.[SiteCode]), '')) AS nvarchar(200)) AS [fromSite],
    CAST(COALESCE(NULLIF(RTRIM(h.[LocCode]), ''), NULLIF(RTRIM(d.[LocCode]), '')) AS nvarchar(200)) AS [fromLocation],
    CAST(NULL AS nvarchar(200)) AS [fromBin],
    CAST(NULL AS nvarchar(200)) AS [toCompany],
    CAST(NULL AS nvarchar(200)) AS [toSite],
    CAST(NULL AS nvarchar(200)) AS [toLocation],
    CAST(NULL AS nvarchar(200)) AS [toBin],
    CAST(RTRIM(h.[CostCode]) AS nvarchar(200)) AS [costCentre]
  FROM dbo.[FiRIssHed] h
  LEFT JOIN dbo.[FiRIssDet] d ON d.[RefNo] = h.[RefNo]
  LEFT JOIN dbo.fItems it ON it.ItemCode = d.[ItemCode]

  UNION ALL

  SELECT
    CAST('fiAccpHed:' + RTRIM(h.[RefNo]) + ISNULL(':' + CAST(d.[RecordId] AS varchar(30)), '') AS nvarchar(200)) AS [lineId],
    CAST(N'Acceptance Note' AS nvarchar(200)) AS [type],
    CAST(RTRIM(h.[TxnType]) AS nvarchar(200)) AS [txnType],
    CAST('fiAccpHed' AS nvarchar(200)) AS [source],
    CAST(RTRIM(h.[RefNo]) AS nvarchar(200)) AS [reference],
    CAST(h.[TxnDate] AS date) AS [date],
    CAST(RTRIM(h.[ManuRef]) AS nvarchar(200)) AS [manualNo],
    CAST(RTRIM(d.[ItemCode]) AS nvarchar(200)) AS [itemCode],
    CAST(RTRIM(it.ItemName) AS nvarchar(200)) AS [itemName],
    CAST(NULL AS nvarchar(200)) AS [machine],
    CAST(d.[Qty] AS numeric(18,4)) AS [quantity],
    CAST(NULL AS nvarchar(200)) AS [fromCompany],
    CAST(NULL AS nvarchar(200)) AS [fromSite],
    CAST(NULL AS nvarchar(200)) AS [fromLocation],
    CAST(NULL AS nvarchar(200)) AS [fromBin],
    CAST(RTRIM(h.[ComCode]) AS nvarchar(200)) AS [toCompany],
    CAST(RTRIM(h.[SiteCode]) AS nvarchar(200)) AS [toSite],
    CAST(RTRIM(h.[LocCode]) AS nvarchar(200)) AS [toLocation],
    CAST(NULL AS nvarchar(200)) AS [toBin],
    CAST(RTRIM(h.[CostCode]) AS nvarchar(200)) AS [costCentre]
  FROM dbo.[fiAccpHed] h
  LEFT JOIN dbo.[fiAccpDet] d ON d.[RefNo] = h.[RefNo]
  LEFT JOIN dbo.fItems it ON it.ItemCode = d.[ItemCode]

  UNION ALL

  SELECT
    CAST('fmRStTrnhed:' + RTRIM(h.[RefNo]) + ISNULL(':' + CAST(d.[RecordId] AS varchar(30)), '') AS nvarchar(200)) AS [lineId],
    CAST(N'Site Transfer Entry-SF' AS nvarchar(200)) AS [type],
    CAST(RTRIM(h.[TxnType]) AS nvarchar(200)) AS [txnType],
    CAST('fmRStTrnhed' AS nvarchar(200)) AS [source],
    CAST(RTRIM(h.[RefNo]) AS nvarchar(200)) AS [reference],
    CAST(h.[TxnDate] AS date) AS [date],
    CAST(RTRIM(h.[ManuRef]) AS nvarchar(200)) AS [manualNo],
    CAST(COALESCE(NULLIF(RTRIM(h.[ItemCode]), ''), NULLIF(RTRIM(d.[ItemCode]), '')) AS nvarchar(200)) AS [itemCode],
    CAST(RTRIM(it.ItemName) AS nvarchar(200)) AS [itemName],
    CAST(NULL AS nvarchar(200)) AS [machine],
    CAST(CASE WHEN d.[RefNo] IS NULL THEN h.[Qty] ELSE d.[Qty] END AS numeric(18,4)) AS [quantity],
    CAST(NULL AS nvarchar(200)) AS [fromCompany],
    CAST(RTRIM(d.[SiteCode]) AS nvarchar(200)) AS [fromSite],
    CAST(COALESCE(NULLIF(RTRIM(h.[LocCode]), ''), NULLIF(RTRIM(d.[LocCode]), '')) AS nvarchar(200)) AS [fromLocation],
    CAST(NULL AS nvarchar(200)) AS [fromBin],
    CAST(NULL AS nvarchar(200)) AS [toCompany],
    CAST(NULL AS nvarchar(200)) AS [toSite],
    CAST(NULL AS nvarchar(200)) AS [toLocation],
    CAST(NULL AS nvarchar(200)) AS [toBin],
    CAST(RTRIM(h.[CostCode]) AS nvarchar(200)) AS [costCentre]
  FROM dbo.[fmRStTrnhed] h
  LEFT JOIN dbo.[fmRStTrnDet] d ON d.[RefNo] = h.[RefNo]
  LEFT JOIN dbo.fItems it ON it.ItemCode = COALESCE(d.[ItemCode], h.[ItemCode])
;
GO

SELECT TOP 20 * FROM dbo.v_inventory_quick ORDER BY [date] DESC;
